//! Exact CESR attachment fixtures generated by the pinned TypeScript reference.

use std::error::Error;

use keri_cesr::crypto::signature::IndexedSignature;
use keri_cesr::sequence::SequenceNumber;
use keri_protocol::attachment::{
    AttachmentError, AttachmentFraming, SealSourceCouple, SealSourceTriple, SignatureSeal, SignedMessageBuilder,
};
use keri_protocol::prefix::IdentifierPrefix;
use keri_protocol::said::Said;
use keri_protocol::serialization::SerializedEvent;
use serde::Deserialize;

const REFERENCE_SHA: &str = "ae92eceb8e776ad57669707bff7f84db9390b711";

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    generated_on: String,
    sources: Vec<String>,
    signatures: Signatures,
    cases: Vec<MessageCase>,
    seal_sources: SealSources,
    rejected_cases: Vec<RejectedCase>,
    reference_quirks: ReferenceQuirks,
}

#[derive(Debug, Deserialize)]
struct Signatures {
    controller: String,
    second: String,
}

#[derive(Debug, Deserialize)]
struct MessageCase {
    name: String,
    event: String,
    attachments: String,
    signature_count: usize,
    seal_kind: Option<String>,
    pipelined: bool,
    raw: String,
    raw_hex: String,
    raw_byte_size: usize,
}

#[derive(Debug, Deserialize)]
struct SealSources {
    triple: TripleCase,
    couple: CoupleCase,
}

#[derive(Debug, Deserialize)]
struct TripleCase {
    identifier: String,
    sequence_number: String,
    said: String,
    framing: String,
    raw: String,
    raw_hex: String,
    reference_function: String,
}

#[derive(Debug, Deserialize)]
struct CoupleCase {
    sequence_number: String,
    said: String,
    framing: String,
    raw: String,
    raw_hex: String,
    reference_function: String,
}

#[derive(Debug, Deserialize)]
struct RejectedCase {
    name: String,
    reference_error_category: String,
    reference_error_message: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct ReferenceQuirks {
    receipt_paths_are_unreachable: ReceiptQuirk,
    seal_sequence_numbers_are_parsed_as_decimal: SequenceQuirk,
    an_unknown_seal_tag_is_ignored: SealTagQuirk,
}

#[derive(Debug, Deserialize)]
struct ReceiptQuirk {
    non_transferable_codex_keys: Vec<String>,
    non_transferable_codex_values: Vec<String>,
    code_is_a_value_not_a_key: bool,
    witness_with_non_transferable_key: RejectedCase,
    receipt_with_non_transferable_key: RejectedCase,
    receipt_with_transferable_key: RejectedCase,
    note: String,
    second_defect: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct SequenceQuirk {
    sequence_a_attachments: String,
    sequence_10_attachments: String,
    sequence_0_attachments: String,
    hex_a_equals_zero: bool,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct SealTagQuirk {
    attachments: String,
    note: String,
    rust_decision: String,
}

fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/fixtures/attachment/v1.json"
    )))?)
}

fn decode_hex(input: &str) -> Result<Vec<u8>, Box<dyn Error>> {
    if !input.len().is_multiple_of(2) {
        return Err("odd-length hexadecimal fixture field".into());
    }
    (0..input.len())
        .step_by(2)
        .map(|index| {
            input
                .get(index..index + 2)
                .ok_or_else(|| Box::<dyn Error>::from("hexadecimal fixture slice out of range"))
                .and_then(|pair| u8::from_str_radix(pair, 16).map_err(Into::into))
        })
        .collect()
}

fn attachment_error_category(error: &AttachmentError) -> &'static str {
    match error {
        AttachmentError::MissingSignatures => "MissingSignatures",
        AttachmentError::TooManySignatures { .. } => "TooManySignatures",
        AttachmentError::NonIntegralQuadlets { .. } => "NonIntegralQuadlets",
        AttachmentError::Prefix { .. } => "Prefix",
        AttachmentError::Said { .. } => "Said",
        AttachmentError::Crypto { .. } => "Crypto",
        AttachmentError::Cesr { .. } => "Cesr",
        _ => "Unknown",
    }
}

/// Rebuilds one fixture case through the Rust builder.
fn build_case(case: &MessageCase, fixture: &Fixture) -> Result<Vec<u8>, Box<dyn Error>> {
    let event = SerializedEvent::parse(case.event.as_bytes())?;
    let controller = IndexedSignature::from_qb64(&fixture.signatures.controller)?;
    let mut signatures = vec![controller];
    if case.signature_count > 1 {
        signatures.push(IndexedSignature::from_qb64(&fixture.signatures.second)?);
    }

    let mut builder = SignedMessageBuilder::new(&event).controller_signatures(signatures);
    if let Some(kind) = &case.seal_kind {
        let identifier =
            IdentifierPrefix::from_qb64(event.sad().get_text("i").ok_or("fixture event carries no identifier")?)?;
        let seal = match kind.as_str() {
            "SealEvent" => SignatureSeal::Event {
                identifier,
                sequence_number: SequenceNumber::from_hex(
                    event.sad().get_text("s").ok_or("fixture event carries no sequence")?,
                )?,
                said: Said::from_qb64(event.sad().get_text("d").ok_or("fixture event carries no SAID")?)?,
            },
            "SealLast" => SignatureSeal::Last { identifier },
            other => return Err(format!("unmapped seal kind {other}").into()),
        };
        builder = builder.seal(seal);
    }
    if case.pipelined {
        builder = builder.framing(AttachmentFraming::Pipelined);
    }
    Ok(builder.build()?.into_bytes())
}

#[test]
fn fixture_metadata_matches_the_pinned_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.upstream, "https://github.com/WebOfTrust/signify-ts.git");
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert_ne!(fixture.generated_on, "");
    assert_eq!(
        fixture.sources,
        [
            "src/keri/core/eventing.ts",
            "src/keri/core/utils.ts",
            "test/core/eventing.test.ts"
        ]
    );
    Ok(())
}

#[test]
fn every_reference_message_is_reproduced_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.cases.len(), 7);

    for case in &fixture.cases {
        let expected = decode_hex(&case.raw_hex)?;
        assert_eq!(expected, case.raw.as_bytes(), "case {} hex/text disagree", case.name);
        assert_eq!(expected.len(), case.raw_byte_size, "case {}", case.name);
        // The recorded event and attachments must together be the recorded message.
        assert_eq!(
            format!("{}{}", case.event, case.attachments),
            case.raw,
            "case {} halves do not reassemble",
            case.name
        );

        let built = build_case(case, &fixture)?;
        assert_eq!(
            core::str::from_utf8(&built)?,
            case.raw,
            "case {} bytes differ",
            case.name
        );
    }
    Ok(())
}

#[test]
fn the_event_and_attachment_boundary_is_retained() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    for case in &fixture.cases {
        let event = SerializedEvent::parse(case.event.as_bytes())?;
        let controller = IndexedSignature::from_qb64(&fixture.signatures.controller)?;
        let message = SignedMessageBuilder::new(&event)
            .controller_signatures(vec![controller])
            .build()?;

        // A caller can verify the event and parse the attachments separately.
        assert_eq!(message.event(), case.event.as_bytes(), "case {}", case.name);
        assert!(message.attachments().starts_with(b"-AAB"), "case {}", case.name);
        assert_eq!(
            [message.event(), message.attachments()].concat(),
            message.as_bytes(),
            "case {}",
            case.name
        );
        // The event half still parses on its own.
        assert_eq!(SerializedEvent::parse(message.event())?.sad(), event.sad());
    }
    Ok(())
}

#[test]
fn the_seal_source_serializers_match() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;

    let triple = &fixture.seal_sources.triple;
    assert_eq!(triple.reference_function, "serializeACDCAttachment");
    assert_eq!(triple.framing, "plain");
    let built = SealSourceTriple::new(
        IdentifierPrefix::from_qb64(&triple.identifier)?,
        SequenceNumber::from_hex(&triple.sequence_number)?,
        Said::from_qb64(&triple.said)?,
    )
    .attachment(AttachmentFraming::Plain)?;
    assert_eq!(core::str::from_utf8(&built)?, triple.raw);
    assert_eq!(built, decode_hex(&triple.raw_hex)?);

    let couple = &fixture.seal_sources.couple;
    assert_eq!(couple.reference_function, "serializeIssExnAttachment");
    assert_eq!(couple.framing, "pipelined");
    let built = SealSourceCouple::new(
        SequenceNumber::from_hex(&couple.sequence_number)?,
        Said::from_qb64(&couple.said)?,
    )
    .attachment(AttachmentFraming::Pipelined)?;
    assert_eq!(core::str::from_utf8(&built)?, couple.raw);
    assert_eq!(built, decode_hex(&couple.raw_hex)?);

    // The reference bakes the framing choice into two differently named functions; Rust makes it
    // an argument, so the other combination is expressible too.
    let plain_couple = SealSourceCouple::new(
        SequenceNumber::from_hex(&couple.sequence_number)?,
        Said::from_qb64(&couple.said)?,
    )
    .attachment(AttachmentFraming::Plain)?;
    assert!(couple.raw.ends_with(core::str::from_utf8(&plain_couple)?));
    Ok(())
}

#[test]
fn reference_rejections_map_to_stable_rust_error_categories() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let case = fixture.rejected_cases.first().ok_or("fixture has no rejections")?;
    assert_eq!(case.name, "no_signatures");
    assert!(case.reference_error_message.contains("Missing attached signatures"));

    let event = SerializedEvent::parse(fixture.cases.first().ok_or("fixture has no cases")?.event.as_bytes())?;
    let error = SignedMessageBuilder::new(&event)
        .build()
        .err()
        .ok_or("an unsigned message was accepted")?;
    assert_eq!(attachment_error_category(&error), case.rust_error_category);
    assert_ne!(case.reference_error_category, "");
    Ok(())
}

#[test]
fn reference_quirks_are_pinned_and_safely_diverged() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;

    // 1. The witness and receipt paths cannot be reached at all.
    let receipts = &quirks.receipt_paths_are_unreachable;
    // The guard tests property keys, and the codes are the values, so it never matches.
    assert!(receipts.non_transferable_codex_keys.iter().any(|key| key == "Ed25519N"));
    assert!(receipts.non_transferable_codex_values.iter().any(|value| value == "B"));
    assert!(
        !receipts.code_is_a_value_not_a_key,
        "`\"B\" in NonTransDex` must be false -- that is the whole defect"
    );
    // Every path throws, including the one with a genuinely non-transferable key.
    for rejection in [
        &receipts.witness_with_non_transferable_key,
        &receipts.receipt_with_non_transferable_key,
        &receipts.receipt_with_transferable_key,
    ] {
        assert!(
            rejection.reference_error_message.contains("tranferable prefix"),
            "expected the misspelled upstream guard message"
        );
        assert_eq!(rejection.rust_error_category, "Blocked");
    }
    assert!(receipts.second_defect.contains("ControllerIdxSigs"));
    assert!(receipts.rust_decision.contains("BLOCKED"));
    assert_ne!(receipts.note, "");

    // 2. Seal sequence numbers are read as decimal, so a seal silently names the wrong event.
    let sequences = &quirks.seal_sequence_numbers_are_parsed_as_decimal;
    assert!(
        sequences.hex_a_equals_zero,
        "hex sequence 'a' must encode identically to zero upstream"
    );
    assert_eq!(sequences.sequence_a_attachments, sequences.sequence_0_attachments);
    assert_ne!(sequences.sequence_10_attachments, sequences.sequence_a_attachments);
    assert_ne!(sequences.note, "");
    assert!(sequences.rust_decision.contains("SequenceNumber"));

    // Rust takes a typed sequence number, so ten and sixteen are distinct and neither is zero.
    let event = SerializedEvent::parse(fixture.cases.first().ok_or("fixture has no cases")?.event.as_bytes())?;
    let controller = IndexedSignature::from_qb64(&fixture.signatures.controller)?;
    let identifier = IdentifierPrefix::from_qb64(event.sad().get_text("i").ok_or("no identifier")?)?;
    let said = Said::from_qb64(event.sad().get_text("d").ok_or("no SAID")?)?;
    let seal_at = |value: u128| -> Result<Vec<u8>, Box<dyn Error>> {
        Ok(SignedMessageBuilder::new(&event)
            .controller_signatures(vec![controller.clone()])
            .seal(SignatureSeal::Event {
                identifier: identifier.clone(),
                sequence_number: SequenceNumber::new(value),
                said,
            })
            .build()?
            .into_bytes())
    };
    let (zero, ten, sixteen) = (seal_at(0)?, seal_at(10)?, seal_at(16)?);
    assert_ne!(ten, zero, "sequence ten must not encode as zero");
    assert_ne!(ten, sixteen);
    // Upstream, the seal the fixture recorded for hex '10' is sixteen's *decimal* reading, ten.
    assert!(
        sequences
            .sequence_10_attachments
            .starts_with(core::str::from_utf8(ten.get(event.raw().len()..).unwrap_or_default())?),
        "the reference encoded hex '10' as decimal ten"
    );

    // 3. An unknown seal tag is silently dropped upstream; in Rust it is unrepresentable.
    let tag = &quirks.an_unknown_seal_tag_is_ignored;
    assert!(
        tag.attachments.starts_with("-AAB"),
        "a misspelled tag produced a message with no seal at all"
    );
    assert!(!tag.attachments.starts_with("-FAB"));
    assert_ne!(tag.note, "");
    assert!(tag.rust_decision.contains("enum"));
    Ok(())
}
